for root,ds,fs in os.walk('studies'):
 for f in fs: print(root,f)

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 for l in gzip.open(f,'rt'):
  if l.startswith('!Sample_') and any(s in l.split('\t')[0] for s in ['title','geo_accession','source_name','characteristics','treatment','growth','description']): print(l.strip())

